// Domain 3 — Centralized management, visibility and troubleshooting flashcards (FortiOS 7.6 / FortiManager 7.6).
export default [
  // 3.1 Centralized management
  { id: 'd3-f001', topic: '3.1', front: 'FGFM protocol and port?', back: 'FortiGate-FortiManager protocol over TLS on **TCP 541**. FortiGate side: `config system central-management`, `set type fortimanager`, `set fmg <ip>`.' },
  { id: 'd3-f002', topic: '3.1', front: 'Which install operation pushes an SD-WAN template?', back: '**Install Device Settings (only)** in the Install Wizard (the guide\'s workflow). SD-WAN is device-level, not part of a policy package; a policy package install also pushes pending device settings.' },
  { id: 'd3-f003', topic: '3.1', front: 'Quick Install (Device DB) vs Install Device Settings (only)?', back: 'Both push the device layer. Quick Install has **no preview** and can\'t be cancelled.' },
  { id: 'd3-f004', topic: '3.1', front: 'Config status "Out of Sync"?', back: 'Changed on the FortiGate and **not** synced to FortiManager (typical when auto-update is disabled). (Modified = changed on FortiManager, not installed; Auto-update = device change synced automatically.)' },
  { id: 'd3-f005', topic: '3.1', front: 'Two ways to resolve a Conflict config status?', back: 'Retrieve Config from the device (then re-import policy), or install FortiManager\'s copy with Install Device Settings (only).' },
  { id: 'd3-f006', topic: '3.1', front: 'FortiManager 7.6 SD-WAN Manager menus?', back: '**Network** (Devices, Monitor), **Templates**, **Overlay Orchestration**, **Rules** (SD-WAN templates).' },
  { id: 'd3-f007', topic: '3.1', front: 'Why isn\'t a managed FortiGate listed in SD-WAN Manager > Network > Devices?', back: 'SD-WAN management isn\'t enabled for it: Device Manager > **More > Enable SD-WAN Management** (or Managed by SD-WAN Manager on a model device).' },
  { id: 'd3-f008', topic: '3.1', front: 'Hide the SD-WAN Manager module?', back: '`config system admin setting` → `set show-sdwan-manager disable` (default enable). Use Device Manager instead.' },
  { id: 'd3-f009', topic: '3.1', front: 'SD-WAN monitoring history default?', back: '**Disabled**: only the last 10 minutes, read live. `set sdwan-monitor-history enable` stores history (180 days by default).' },
  { id: 'd3-f010', topic: '3.1', front: 'Sections of a FortiManager SD-WAN template?', back: 'SD-WAN Zones (members, zones), SD-WAN Rules, Performance SLA, Neighbor, Duplication, Advanced Options.' },
  { id: 'd3-f011', topic: '3.1', front: 'Can SD-WAN template members use normalized interfaces?', back: '**No.** Bind by interface name, or use a metadata variable (Interface Member and Gateway IP accept them).' },
  { id: 'd3-f012', topic: '3.1', front: 'Prefix on SD-WAN templates imported from a FortiGate?', back: '`Import`.' },
  { id: 'd3-f013', topic: '3.1', front: 'Default policy blocks an SD-WAN template install. Why?', back: 'An interface referenced directly in a firewall policy can\'t be an SD-WAN member. Delete the policy or install a package without it.' },
  { id: 'd3-f014', topic: '3.1', front: 'Template group rule for template types?', back: '**One template per type** (system, IPsec, static route, BGP, SD-WAN, CLI, ...); only AP profiles allow several. FortiManager installs them in the right order.' },
  { id: 'd3-f015', topic: '3.1', front: 'Preview CLI Configuration vs Install Preview for metadata variables?', back: 'Preview CLI Configuration shows **variable names**; Install Preview shows the **resolved values**.' },
  { id: 'd3-f016', topic: '3.1', front: 'What the SD-WAN overlay template does NOT do?', back: 'It gives **no SD-WAN intelligence** (no rules or steering) and assumes hub-branch underlay connectivity already exists.' },
  { id: 'd3-f017', topic: '3.1', front: 'Overlay wizard defaults?', back: 'Overlay `10.10.0.0/16`, loopbacks `172.16.0.0/16`, BGP AS `65000`; BGP on Loopback, Dynamic BGP and ADVPN 2.0 enabled.' },
  { id: 'd3-f018', topic: '3.1', front: 'Metadata variable created by the overlay wizard?', back: '`branch_id`: unique per branch, set per device or by **Automatic Branch ID Assignment**.' },
  { id: 'd3-f019', topic: '3.1', front: 'Metadata variable value precedence?', back: 'Per-device value > device-group value > default value. (Global Database ADOM uses per-ADOM mapping.)' },
  { id: 'd3-f020', topic: '3.1', front: 'Where are ADOM-level metadata variables created, and how are they referenced?', back: 'Policy & Objects > Advanced > Metadata Variables. Type `$` to pick one, or write `$(name)` in CLI templates and scripts.' },

  // 3.2 Logs and widgets
  { id: 'd3-f021', topic: '3.2', front: 'logid 0100022921?', back: '"Routing information changed": health check down/up, static routes on the member may be removed/added. **subtype system**, level critical.' },
  { id: 'd3-f022', topic: '3.2', front: 'logid 0113022923?', back: '"SDWAN status": eventtype **Health Check** (in/out of SLA, number of pass members) or **Service** (member order, stop/start forwarding, load-balance set).' },
  { id: 'd3-f023', topic: '3.2', front: 'logid 0113022924?', back: '"SDWAN volume status": a member is over (conservative status) or back under its session/volume ratio.' },
  { id: 'd3-f024', topic: '3.2', front: 'logid 0113022925?', back: '"SDWAN SLA information": periodic latency/jitter/loss/slamap, every `sla-fail-log-period` / `sla-pass-log-period` seconds.' },
  { id: 'd3-f025', topic: '3.2', front: 'Default sla-fail-log-period and sla-pass-log-period?', back: '**0** (range 0-3600 s): no periodic SLA logs until set.' },
  { id: 'd3-f026', topic: '3.2', front: 'In an SD-WAN event log, member="2" and seq="2,1" mean?', back: '`member` = member **sequence number**; `seq` = the rule\'s new member order (member 2 now preferred).' },
  { id: 'd3-f027', topic: '3.2', front: 'SD-WAN fields in forward traffic logs?', back: '`vwlid` (rule ID), `vwlname` (rule name), `vwlquality` (matched rule\'s member quality), `vwlservice` (matched application).' },
  { id: 'd3-f028', topic: '3.2', front: 'Traffic log with no vwlid/vwlname?', back: 'The session didn\'t match a configured SD-WAN rule (the vwl fields describe the matched rule): it followed the FIB (implicit rule) or another route. Confirm with debug flow or `sdwan_service_id`.' },
  { id: 'd3-f029', topic: '3.2', front: 'SD-WAN Zones tab views?', back: '**Bandwidth** (down/up per interface), **Volume** (donuts of bytes), **Sessions** (donut of active sessions).' },
  { id: 'd3-f030', topic: '3.2', front: 'Checkmark on the SD-WAN Rules tab?', back: 'The member currently selected by the rule; hover for the reason. The Hit Count column shows matches.' },
  { id: 'd3-f031', topic: '3.2', front: 'Performance SLAs tab arrow colours?', back: 'Green = active, red = inactive at the last check. It doesn\'t show SLA pass/fail.' },
  { id: 'd3-f032', topic: '3.2', front: 'GUI view of policy routes including SD-WAN rules?', back: 'Dashboard > Network > **Static & Dynamic Routing** widget, toggled to **Policy**.' },

  // 3.3 Troubleshooting
  { id: 'd3-f033', topic: '3.3', front: 'sla_map=0x3?', back: 'The member meets SLA entries **1 and 2** (bit 0 = ID 1, bit 1 = ID 2). 0x0 = meets none.' },
  { id: 'd3-f034', topic: '3.3', front: 'When is a member dead / alive again?', back: 'Dead after `failtime` consecutive failures (default 5); alive after `recoverytime` successes (default 5). Default interval 500 ms.' },
  { id: 'd3-f035', topic: '3.3', front: 'service vs service4?', back: 'Since 7.4.4, `diagnose sys sdwan service` is split into `service4` (IPv4) and `service6` (IPv6).' },
  { id: 'd3-f036', topic: '3.3', front: 'Manual rule in service4: both members "selected". Which is used?', back: 'The **first** listed. All selected members are used only when load balancing is enabled.' },
  { id: 'd3-f037', topic: '3.3', front: 'service4 Mode names?', back: '`manual`, `priority` (Best Quality), `sla` (Lowest Cost (SLA)), `load-balance hash-mode=...` (SLA rule + load balancing), `manual hash-mode=...` (Manual + load balancing), `auto` (legacy).' },
  { id: 'd3-f038', topic: '3.3', front: 'What does diagnose sys sdwan member describe?', back: 'Members and the **implicit rule** state: session count (weight), volume room/overload (volume), spillover thresholds and over-bps flags (usage).' },
  { id: 'd3-f039', topic: '3.3', front: 'sla-log vs intf-sla-log?', back: '`sla-log <hc> <seq>`: ~10 min of probe results per member. `intf-sla-log <intf>`: ~15 min of bandwidth per interface.' },
  { id: 'd3-f040', topic: '3.3', front: 'Find an SD-WAN rule in diagnose firewall proute list?', back: '`vwl_service=<id>(<name>)`; `vwl_mbr_seq` and `oif` list members in current order; `hit_count` shows use.' },
  { id: 'd3-f041', topic: '3.3', front: 'Debug flow line for an SD-WAN rule or policy route match?', back: '`func=rpdb_srv_match_input` `msg="Match policy routing id=<id>: to <dst> via ifindex-<n>"`.' },
  { id: 'd3-f042', topic: '3.3', front: 'Debug flow: no "Match policy routing" line?', back: 'No policy route or SD-WAN rule matched; the egress came from the FIB (implicit rule over the member routes).' },
  { id: 'd3-f043', topic: '3.3', front: '"Denied by forward policy check (policy 0)"?', back: 'No firewall policy matched: the implicit deny. Check policies for the egress **zone**.' },
  { id: 'd3-f044', topic: '3.3', front: 'Two FIB checks before an SD-WAN rule member is used?', back: '1) FIB best match for the destination is an SD-WAN member. 2) A FIB route to the destination exists over the chosen member.' },
  { id: 'd3-f045', topic: '3.3', front: 'set default enable + set gateway enable on a rule?', back: 'Skips the FIB checks and sends matching traffic to the member\'s configured gateway. Both default to disable; CLI only.' },
  { id: 'd3-f046', topic: '3.3', front: 'SD-WAN fields in diagnose sys session list?', back: '`sdwan_mbr_seq` (member) and `sdwan_service_id` (rule). Also check `dev=`, `gwy=` and the `act=snat` tuple.' },
  { id: 'd3-f047', topic: '3.3', front: 'Safe way to force one session to re-route?', back: '`diagnose sys session filter clear` → `filter dst <ip>` → `list` → `diagnose sys session clear` (clears only filtered sessions).' },
  { id: 'd3-f048', topic: '3.3', front: 'Why does a SNAT session stay on the backup member after recovery?', back: 'SNAT sessions keep their egress while the old route is valid, unless `config system global` → `set snat-route-change enable`.' },
  { id: 'd3-f049', topic: '3.3', front: 'Member dead and its static route gone from the table?', back: '`update-static-route` (default enable) withdrew the member\'s static routes; log 0100022921. They return on recovery.' },
  { id: 'd3-f050', topic: '3.3', front: 'Health check `set members 0` with a private DC server?', back: '0 = all members probe it; underlays can\'t reach the private server and show dead. Limit members to the overlays.' },
];
